/* Nish runtime, the bcrypt half: EksBlowfish's cost loop on x86-64 kernels
 * written in assembly. std/crypto/bcrypt.ts is bcrypt; this is a faster body
 * for its private `bcryptBodyN`, the 521 chained Blowfish encryptions that
 * rewrite each lane's P-array and S-boxes, which the compiler calls in that
 * function's place when `nish_bcrypt_hw` says this machine can run it
 * (src/kernels.ts).
 *
 * A translation unit of its own for runtime-sha256.c's reason: its own
 * measured `.text*` ceiling in tests/runtime-budgets.js, and a program that
 * hashes no password links none of it. Each kernel is in a section of its own
 * on ELF (and an atom of its own on Mach-O), so section GC keeps only what the
 * dispatch below names.
 *
 * One path, on x86-64 with BMI1 and BMI2 (`bextr`, `rorx`). The kernels are
 * generated, between the BEGIN GENERATED and END GENERATED lines, by
 * runtime/gen-bcrypt-x86-64.mjs, whose header says how they are built; `node
 * tests/run.js bcrypt-asm` fails when that text and the generator differ. A
 * machine without BMI1 and BMI2, or a process with `NISH_BCRYPT=soft`, runs
 * the Nish code in std/crypto/bcrypt.ts instead: the compiler keeps that code
 * and branches on `nish_bcrypt_hw` at each call. Every other target, wasm32
 * and AArch64 included, compiles `nish_bcrypt_hw` to `return 0` and the kernel
 * to a trap nothing reaches, so a link that names it still resolves.
 *
 * The generator writes two index styles, `ah` and `bextr`; this file runs
 * `bextr` at every width, because it measured as fast or faster at every width
 * (docs/security/crypto-bcrypt-hw.md, "Speed"), and keeps `ah` for the tests
 * and for the next machine's measurement. Section GC drops it from programs.
 *
 * The kernel checks the width and the state's length and returns 0 without
 * touching anything when either is out of range, so the caller runs the Nish
 * function: a width outside 2 to 6 does nothing there, and a short state
 * panics with its own message, so both paths behave the same.
 *
 * Not constant time, by bcrypt's design: every S-box load is indexed by a
 * byte of the secret state, exactly as the Nish code's are. Wiping: each
 * kernel zeroes its stack frame and every caller-saved register it wrote
 * before it returns (docs/security/crypto-bcrypt-hw.md).
 *
 * The kernels are adapted from the multicore-server-challenge submission
 * rust-epoll-WorriedArrow (submissions/rust-epoll-WorriedArrow/build.rs).
 * Copyright (c) 2026 arjaythedev and the challenge contributors.
 * MIT License; see runtime/LICENSE-multicore-server-challenge.
 */
