/* Named here rather than through <stdlib.h>, for runtime-aes.c's reason. */
char *getenv(const char *name);

/* How a kernel's symbol is spelled: hidden, in a section of its own on ELF,
   with an underscore and as a private extern on Mach-O. */
#define NISH_BCRYPT_HIDDEN __attribute__((visibility("hidden")))
#if defined(__APPLE__)
#define NISH_BCRYPT_BEGIN(name) ".text\n.globl _" name "\n.private_extern _" name "\n.p2align 4\n_" name ":\n"
#define NISH_BCRYPT_END(name) ""
#else
#define NISH_BCRYPT_BEGIN(name) \
  ".section .text." name ",\"ax\",@progbits\n.globl " name "\n.hidden " name "\n.type " name ", @function\n.p2align 4\n" name ":\n"
#define NISH_BCRYPT_END(name) ".size " name ", .-" name "\n"
#endif

