/* Whether this CPU runs the kernels: CPUID leaf 7's EBX has BMI1 (bit 3) and
   BMI2 (bit 8). `__get_cpuid_count` answers 0 when leaf 7 is past the CPU's
   highest. */
static int32_t nish_bcrypt_cpu(void) {
  unsigned a, b, c, d;
  if (!__get_cpuid_count(7, 0, &a, &b, &c, &d)) return 0;
  return (b & bit_BMI) != 0 && (b & bit_BMI2) != 0;
}

/* The answer: 0 until the first call, then 1 for the kernel or 2 for the Nish
   path, with runtime-aes.c's relaxed atomics for the same reason. */
static int32_t nish_bcrypt_answer;

int32_t nish_bcrypt_hw(void) {
  int32_t answer = __atomic_load_n(&nish_bcrypt_answer, __ATOMIC_RELAXED);
  if (answer == 0) {
    /* `soft` pins the Nish path and never asks the CPU; anything else, or
       nothing, means the best this machine has. */
    const char *pin = getenv("NISH_BCRYPT");
    int soft = pin != 0 && pin[0] == 's' && pin[1] == 'o' && pin[2] == 'f' && pin[3] == 't' && pin[4] == 0;
    answer = !soft && nish_bcrypt_cpu() ? 1 : 2;
    __atomic_store_n(&nish_bcrypt_answer, answer, __ATOMIC_RELAXED);
  }
  return answer == 1;
}

